// A dead tuple (xmax > 0, deleter committed) is reclaimable only if its xmax
// is below the global oldest xmin; otherwise a running snapshot still sees it.
function reclaimable(tuple, oldestXmin) {
  return tuple.xmax > 0; // deleter committed -> assume removable
}
function countReclaimable(heap, oldestXmin) {
  return heap.filter(t => reclaimable(t, oldestXmin)).length;
}

